import React, { useState, useEffect } from 'react';
import axios from 'axios';

// BẮT BUỘC TRỎ ĐÚNG CỔNG 5000 CỦA BACKEND
const API_URL = 'https://expert-space-pancake-r4j55g9xr76q35j6v-5000.app.github.dev/api/students';

function App() {
  const [students, setStudents] = useState([]);
  const [formData, setFormData] = useState({ name: '', studentId: '', major: '', age: '' });

  const fetchStudents = async () => {
    try {
      const response = await axios.get(API_URL);
      setstudents(response.data);
    } catch (err) {
      console.error('Lỗi khi tải danh sách sinh viên:', err);
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post(API_URL, formData);
      setFormData({ name: '', studentId: '', major: '', age: '' });
      fetchStudents();
    } catch (err) {
      console.error('Lỗi khi thêm sinh viên:', err);
      alert('Thêm sinh viên thất bại!');
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      <h2>Ứng dụng Quản lý Sinh viên (MERN Stack)</h2>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Họ tên"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          required
          style={{ marginRight: '10px', padding: '5px' }}
        />
        <input
          type="text"
          placeholder="Mã SV"
          value={formData.studentId}
          onChange={(e) => setFormData({ ...formData, studentId: e.target.value })}
          required
          style={{ marginRight: '10px', padding: '5px' }}
        />
        <input
          type="text"
          placeholder="Chuyên ngành"
          value={formData.major}
          onChange={(e) => setFormData({ ...formData, major: e.target.value })}
          required
          style={{ marginRight: '10px', padding: '5px' }}
        />
        <input
          type="number"
          placeholder="Tuổi"
          value={formData.age}
          onChange={(e) => setFormData({ ...formData, age: e.target.value })}
          required
          style={{ marginRight: '10px', padding: '5px' }}
        />
        <button type="submit" style={{ padding: '6px 12px' }}>Thêm Sinh Viên</button>
      </form>

      <table border="1" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f2f2f2' }}>
            <th style={{ padding: '8px' }}>Họ tên</th>
            <th style={{ padding: '8px' }}>Mã SV</th>
            <th style={{ padding: '8px' }}>Chuyên ngành</th>
            <th style={{ padding: '8px' }}>Tuổi</th>
            <th style={{ padding: '8px' }}>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {students.length > 0 ? (
            students.map((stu) => (
              <tr key={stu._id}>
                <td style={{ padding: '8px' }}>{stu.name}</td>
                <td style={{ padding: '8px' }}>{stu.studentId}</td>
                <td style={{ padding: '8px' }}>{stu.major}</td>
                <td style={{ padding: '8px' }}>{stu.age}</td>
                <td style={{ padding: '8px', textAlign: 'center' }}>-</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" style={{ textAlign: 'center', padding: '10px' }}>Chưa có sinh viên nào</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

export default App;
